import catalog from "./font-catalog.json";
import { applyTextCase, type TextCase } from "./text-case";

export type FontCategory = "sans-serif" | "serif" | "display" | "script" | "monospace";

export type CatalogFont = { family: string; category: FontCategory; bold: boolean; italic: boolean };

/**
 * The built-in font list: Google Fonts families bundled from @fontsource (regular and bold with
 * their italics, where the family has them), so text renders the same without internet access.
 * Generated by scripts/generate-fonts.ts; the stylesheets declaring the faces are imported by the
 * editor (components/editor/font-faces.ts).
 */
export const FONT_CATALOG = catalog as CatalogFont[];

export const FONT_CATEGORIES: { id: FontCategory; label: string }[] = [
  { id: "sans-serif", label: "Bezpatková" },
  { id: "serif", label: "Patková" },
  { id: "display", label: "Ozdobná" },
  { id: "script", label: "Psací" },
  { id: "monospace", label: "Neproporcionální" },
];

export const DEFAULT_FONT_FAMILY = "Inter";

const BUILT_IN = new Set(FONT_CATALOG.map((f) => f.family.toLowerCase()));

export function isBuiltInFamily(family: string): boolean {
  return BUILT_IN.has(family.trim().toLowerCase());
}

/** Catalog fonts whose name contains the query (case-insensitive), in catalog order. */
export function searchFonts(fonts: CatalogFont[], query: string, category: FontCategory | null): CatalogFont[] {
  const q = query.trim().toLowerCase();
  return fonts.filter((f) => (!category || f.category === category) && (!q || f.family.toLowerCase().includes(q)));
}

export type FontNeed = { family: string; weight: "400" | "700"; style: "normal" | "italic"; text: string };

export function normalizeWeight(weight: unknown): "400" | "700" {
  if (weight === "bold") return "700";
  const n = typeof weight === "number" ? weight : Number(weight);
  return Number.isFinite(n) && n >= 600 ? "700" : "400";
}

/** Every font face (family, weight, style) the given object JSON draws text with, and the text it draws. */
export function fontNeedsOf(objects: Record<string, unknown>[]): FontNeed[] {
  const needs = new Map<string, FontNeed>();
  const visit = (o: Record<string, unknown>) => {
    if (typeof o.fontFamily === "string" && typeof o.text === "string") {
      const need: FontNeed = {
        family: o.fontFamily,
        weight: normalizeWeight(o.fontWeight),
        style: o.fontStyle === "italic" ? "italic" : "normal",
        // List markers are drawn with the text's font too.
        text: applyTextCase(o.text, o.textCase as TextCase | undefined) + (o.listStyle ? "•0123456789." : ""),
      };
      const key = `${need.family}|${need.weight}|${need.style}`;
      const existing = needs.get(key);
      needs.set(key, existing ? { ...existing, text: existing.text + need.text } : need);
    }
    // Charts draw their labels in the chart's font.
    const chart = o.chart as { fontFamily?: unknown; labels?: unknown[]; series?: { name?: unknown }[] } | undefined;
    if (chart && typeof chart.fontFamily === "string") {
      const text = [...(chart.labels ?? []).map(String), ...(chart.series ?? []).map((s) => String(s?.name ?? "")), "0123456789.,-%"].join(" ");
      const key = `${chart.fontFamily}|400|normal`;
      const existing = needs.get(key);
      needs.set(key, existing ? { ...existing, text: existing.text + text } : { family: chart.fontFamily, weight: "400", style: "normal", text });
    }
    // Tables keep their text in cells, all in the table's font.
    const table = o.table as { cells?: { text?: unknown }[][] } | undefined;
    if (typeof o.fontFamily === "string" && Array.isArray(table?.cells)) {
      const text = table.cells.flat().map((c) => (typeof c?.text === "string" ? c.text : "")).join(" ");
      const need: FontNeed = { family: o.fontFamily, weight: "400", style: "normal", text: text || "Aa" };
      const key = `${need.family}|400|normal`;
      const existing = needs.get(key);
      needs.set(key, existing ? { ...existing, text: existing.text + need.text } : need);
    }
    if (Array.isArray(o.objects)) o.objects.forEach((child) => visit(child as Record<string, unknown>));
  };
  objects.forEach(visit);
  return [...needs.values()];
}

export function fontShorthand(need: Pick<FontNeed, "family" | "weight" | "style">): string {
  return `${need.style} ${need.weight} 40px "${need.family}"`;
}

/**
 * Loads the faces before text is measured: Fabric measures with whatever font is available at
 * that moment. Passing the text matters, because each face is split into unicode-range subsets
 * (latin, latin-ext for Czech, ...) that only load for characters actually used.
 */
export async function loadFonts(needs: FontNeed[]): Promise<void> {
  await Promise.all(
    needs.map((n) => document.fonts.load(fontShorthand(n), n.text || "A").catch(() => [])),
  );
}
